import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;

import com.example.contact.SentMessage;
import com.vaadin.browserless.SpringBrowserlessTest;
import com.vaadin.flow.component.Key;
import com.vaadin.flow.component.button.Button;
import com.vaadin.flow.component.dialog.Dialog;
import com.vaadin.flow.component.grid.Grid;
import com.vaadin.flow.component.html.H1;
import com.vaadin.flow.component.notification.Notification;
import com.vaadin.flow.component.textfield.EmailField;
import com.vaadin.flow.component.textfield.TextArea;
import com.vaadin.flow.component.textfield.TextField;
import com.vaadin.flow.router.RouterLink;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;

@SpringBootTest
class ContactViewTest extends SpringBrowserlessTest {

    @Test
    void contactViewHasHeadingFieldsAndEnabledSendButton() {
        var view = navigate(ContactView.class);

        assertEquals("Contact", $(H1.class).single().getText());
        assertEquals("About", $(RouterLink.class).single().getText());
        assertEquals("Name", $(TextField.class).withLabel("Name").single().getLabel());
        assertEquals("Email", $(EmailField.class).single().getLabel());
        assertEquals("Phone", $(TextField.class).withLabel("Phone").single().getLabel());
        assertEquals("Message", $(TextArea.class).single().getLabel());
        assertEquals("", $(TextField.class).withLabel("Name").single().getValue());
        assertTrue($(Button.class).withCaption("Send").single().isEnabled());
        assertTrue(view.isAttached());
    }

    @Test
    void emptySendShowsRequiredErrorsAndSendsNothing() {
        navigate(ContactView.class);
        int before = listedMessages().size();

        $(Button.class).withCaption("Send").single().click();

        assertTrue($(TextField.class).withLabel("Name").single().isInvalid());
        assertEquals("Name is required", $(TextField.class).withLabel("Name").single().getErrorMessage());
        assertEquals("Give an e-mail address or a phone number", $(EmailField.class).single().getErrorMessage());
        assertEquals("Message is required", $(TextArea.class).single().getErrorMessage());
        assertEquals(before, listedMessages().size());
        assertFalse($(Notification.class).exists());
    }

    @Test
    void invalidEmailIsRejectedAndTypedValuesStay() {
        navigate(ContactView.class);
        $(TextField.class).withLabel("Name").single().setValue("Ann");
        $(EmailField.class).single().setValue("not-an-address");
        $(TextArea.class).single().setValue("Hello");

        $(Button.class).withCaption("Send").single().click();

        assertEquals("Enter a valid e-mail address", $(EmailField.class).single().getErrorMessage());
        assertFalse($(TextField.class).withLabel("Name").single().isInvalid());
        assertEquals("Ann", $(TextField.class).withLabel("Name").single().getValue());
        assertEquals("Hello", $(TextArea.class).single().getValue());
    }

    @Test
    void tooLongMessageIsRejected() {
        navigate(ContactView.class);
        $(TextField.class).withLabel("Name").single().setValue("Ann");
