+package com.example.views;
+
+import java.time.LocalDateTime;
+import java.time.format.DateTimeFormatter;
+import java.util.regex.Pattern;
+
+import com.example.contact.MessageStore;
+import com.example.contact.SentMessage;
+import com.vaadin.flow.component.AttachEvent;
+import com.vaadin.flow.component.DetachEvent;
+import com.vaadin.flow.component.HasValidation;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.Shortcuts;
+import com.vaadin.flow.component.ShortcutRegistration;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.button.ButtonVariant;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveEvent.ContinueNavigationAction;
+import com.vaadin.flow.router.RouterLink;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final int MAX_MESSAGE_LENGTH = 500;
+    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
+    private static final DateTimeFormatter SENT_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");
+
+    private final MessageStore store;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<SentMessage> grid = new Grid<>();
+
+    private final Dialog leaveDialog = new Dialog();
+    private ContinueNavigationAction pendingNavigation;
+
+    private ShortcutRegistration enterShortcut;
+
+    public ContactView(MessageStore store) {
+        this.store = store;
+
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+        name.addValueChangeListener(e -> send.setEnabled(true));
+        email.addValueChangeListener(e -> send.setEnabled(true));
+        phone.addValueChangeListener(e -> send.setEnabled(true));
+        message.addValueChangeListener(e -> send.setEnabled(true));
+
+        send.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        send.addClickListener(e -> sendMessage());
+
+        grid.addColumn(SentMessage::name).setHeader("Name");
+        grid.addColumn(SentMessage::email).setHeader("Email");
+        grid.addColumn(SentMessage::phone).setHeader("Phone");
+        grid.addColumn(SentMessage::message).setHeader("Message").setAutoWidth(true);
+        grid.addColumn(m -> m.sentAt().format(SENT_FORMAT)).setHeader("Sent");
+        grid.setItems(store.newestFirst());
+
+        leaveDialog.setHeaderTitle("Discard message?");
+        leaveDialog.add(new Paragraph("You have unsent input. Leaving this page will discard it."));
+        leaveDialog.getFooter().add(
+                new Button("Keep editing", e -> leaveDialog.close()),
+                new Button("Discard", e -> discardAndLeave()));
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class),
+                new FormLayout(name, email, phone, message), send, grid, leaveDialog);
+    }
+
+    @Override
+    protected void onAttach(AttachEvent attachEvent) {
+        super.onAttach(attachEvent);
+        enterShortcut = Shortcuts.addShortcutListener(attachEvent.getUI(), this::sendOnEnter, Key.ENTER);
+    }
+
+    @Override
+    protected void onDetach(DetachEvent detachEvent) {
+        enterShortcut.remove();
+        super.onDetach(detachEvent);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasUnsentInput()) {
+            pendingNavigation = event.postpone();
+            leaveDialog.open();
+        }
+    }
+
+    private boolean hasUnsentInput() {
+        return !name.getValue().isEmpty() || !email.getValue().isEmpty()
+                || !phone.getValue().isEmpty() || !message.getValue().isEmpty();
+    }
+
+    private void discardAndLeave() {
+        var navigation = pendingNavigation;
+        pendingNavigation = null;
+        leaveDialog.close();
+        if (navigation != null) {
+            navigation.proceed();
+        }
+    }
+
+    private void sendOnEnter() {
+        if (send.isEnabled() && !leaveDialog.isOpened()) {
+            sendMessage();
+        }
+    }
+
+    private void sendMessage() {
+        name.setInvalid(false);
+        email.setInvalid(false);
+        phone.setInvalid(false);
+        message.setInvalid(false);
+
+        var senderName = name.getValue().strip();
+        var senderEmail = email.getValue().strip();
+        var senderPhone = phone.getValue().strip();
+        var text = message.getValue().strip();
+
+        boolean valid = true;
+        if (senderName.isEmpty()) {
+            invalid(name, "Name is required");
+            valid = false;
+        }
+        if (senderEmail.isEmpty()) {
+            if (senderPhone.isEmpty()) {
+                invalid(email, "Give an e-mail address or a phone number");
+                valid = false;
+            }
+        } else if (!EMAIL.matcher(senderEmail).matches()) {
+            invalid(email, "Enter a valid e-mail address");
+            valid = false;
+        }
+        if (text.isEmpty()) {
+            invalid(message, "Message is required");
+            valid = false;
+        } else if (text.length() > MAX_MESSAGE_LENGTH) {
+            invalid(message, "Message must be at most 500 characters");
+            valid = false;
+        }
+        if (!valid) {
+            return;
+        }
+
+        store.add(new SentMessage(senderName, senderEmail, senderPhone, text, LocalDateTime.now()));
+        grid.setItems(store.newestFirst());
+
+        // Clearing fires value change events, which would re-enable Send, so disable it afterwards.
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        send.setEnabled(false);
+
+        Notification.show("Message sent");
+    }
+
+    private static void invalid(HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+}
